import{_ as t,o,c as s,a2 as n}from"./chunks/framework.CqdVOxXJ.js";const u=JSON.parse('{"title":"4. Sales agent playbook","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/04-sales-agent-guide.md","filePath":"chapters/04-sales-agent-guide.md","lastUpdated":null}'),r={name:"chapters/04-sales-agent-guide.md"};function a(i,e,l,d,g,h){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="_4-sales-agent-playbook" tabindex="-1">4. Sales agent playbook <a class="header-anchor" href="#_4-sales-agent-playbook" aria-label="Permalink to &quot;4. Sales agent playbook&quot;">​</a></h1><p><strong>For:</strong> Sales Agent (owner sections marked) · <strong>Hubs:</strong> Sales, Me</p><p>As a Sales Agent you bring customers to the shop and follow them up until the car comes in. The workshop desk turns your inquiries into jobs and runs the repair. You earn commission on customers you referred, after the shop has been paid.</p><table tabindex="0"><thead><tr><th>Page</th><th>Path</th><th>Sales Agent sees</th><th>Owner sees</th></tr></thead><tbody><tr><td>My pipeline / Pipeline</td><td><code>/sales/pipeline</code></td><td>Your own inquiries (your Sales Agent home page)</td><td>Every inquiry, with a Sales person filter</td></tr><tr><td>My commission / Commission</td><td><code>/sales</code> (also <code>/me/commission</code>)</td><td>Your commission lines and payouts</td><td>All lines, payouts, <strong>Pay due fees</strong></td></tr><tr><td>Monitoring</td><td><code>/sales/monitoring</code></td><td>Your quota, actual and performance</td><td>Whole team, mix, imports, quota editing</td></tr><tr><td>Incentives</td><td><code>/sales/incentives</code> (also <code>/me/incentive</code>)</td><td>Your quarterly target and progress</td><td>Set targets, record bonuses</td></tr><tr><td>Insurance</td><td><code>/sales/insurance</code></td><td>Premium calculator and saved estimates</td><td>Same, plus the <strong>Rate table</strong></td></tr></tbody></table><h2 id="_4-1-sales-home-and-why-you-do-not-create-workshop-jobs" tabindex="-1">4.1 Sales home and why you do not create workshop jobs <a class="header-anchor" href="#_4-1-sales-home-and-why-you-do-not-create-workshop-jobs" aria-label="Permalink to &quot;4.1 Sales home and why you do not create workshop jobs&quot;">​</a></h2><p><strong>Sales</strong> is your home hub. You do <strong>not</strong> use <strong>Workshop › New job</strong>: that screen is for the owner/desk only. Instead:</p><ol><li>You log the customer as an <strong>inquiry</strong> in your pipeline. The app creates the job at status <strong>New inquiry</strong> on the <strong>Sales</strong> channel, with you as the <strong>Sales advisor</strong>.</li><li>The desk confirms the booking, quotes, and runs the repair from the job workspace.</li><li>You can open any of your jobs from the pipeline to <strong>view</strong> it (status, quote total, estimate print). You cannot change status, lines or money.</li></ol><p>This keeps one record per car, keeps prices and margins at the desk, and makes sure commission is attributed correctly (see 4.4).</p><h2 id="_4-2-sales-pipeline-sales-pipeline" tabindex="-1">4.2 Sales Pipeline (<code>/sales/pipeline</code>) <a class="header-anchor" href="#_4-2-sales-pipeline-sales-pipeline" aria-label="Permalink to &quot;4.2 Sales Pipeline (`/sales/pipeline`)&quot;">​</a></h2><p>The pipeline lists inquiries that are not yet in the shop: <strong>New inquiry</strong>, <strong>For canvass</strong>, <strong>Booked</strong>, <strong>Quoted</strong> and <strong>Waiting for LOA</strong>. Filter with the status chips (<strong>All open</strong> first) and <strong>Follow-up due (n)</strong>.</p><h3 id="add-an-inquiry" tabindex="-1">Add an inquiry <a class="header-anchor" href="#add-an-inquiry" aria-label="Permalink to &quot;Add an inquiry&quot;">​</a></h3><ol><li>Press <strong>New inquiry</strong>.</li><li>Fill <strong>Customer name</strong>, <strong>Mobile</strong>, <strong>Plate</strong> (required) and optionally <strong>Email</strong>, <strong>Year</strong>, <strong>Make</strong>, <strong>Model</strong>.</li><li>In <strong>What do they want?</strong> describe the request (3–1000 characters), for example &quot;Rear bumper dent, wants insurance claim with Malayan&quot;.</li><li>Set <strong>Next follow-up</strong> (required for Sales; defaults to tomorrow).</li><li>Press <strong>Add inquiry</strong>.</li></ol><h3 id="work-the-list" tabindex="-1">Work the list <a class="header-anchor" href="#work-the-list" aria-label="Permalink to &quot;Work the list&quot;">​</a></h3><p>Each row shows <strong>Job</strong>, <strong>Customer</strong>, <strong>Car</strong>, <strong>Sales advisor</strong>, <strong>Status</strong>, <strong>Age</strong>, <strong>Last moved</strong>, <strong>Next follow-up</strong> and the <strong>Quote</strong> total.</p><ul><li><strong>Set follow-up</strong> — new date plus an optional <strong>Note</strong> (saved to the job&#39;s internal notes).</li><li><strong>Print estimate</strong> — the customer-facing estimate (sell prices only).</li><li><strong>Mark lost</strong> — only on New inquiry rows. Give a reason (at least 3 characters). The job is cancelled with that reason.</li></ul><div class="tip custom-block"><p class="custom-block-title">Daily habit</p><p>Open <strong>Follow-up due</strong> every morning. Overdue follow-ups are highlighted.</p></div><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/04-sales-agent-guide/01-pipeline.png</code> — My pipeline with status chips and Follow-up due filter.</p></div><h2 id="_4-3-sales-monitoring-and-spreadsheet-import-sales-monitoring" tabindex="-1">4.3 Sales Monitoring and spreadsheet import (<code>/sales/monitoring</code>) <a class="header-anchor" href="#_4-3-sales-monitoring-and-spreadsheet-import-sales-monitoring" aria-label="Permalink to &quot;4.3 Sales Monitoring and spreadsheet import (`/sales/monitoring`)&quot;">​</a></h2><p>Monitoring replaces the monthly sales monitoring spreadsheets.</p><h3 id="how-sales-are-counted-this-month" tabindex="-1">How sales are counted this month <a class="header-anchor" href="#how-sales-are-counted-this-month" aria-label="Permalink to &quot;How sales are counted this month&quot;">​</a></h3><ul><li>An <strong>insurance</strong> job counts its <strong>LOA amount</strong> in the month the LOA is dated. Each supplement counts in the month it was approved.</li><li><strong>Any other job</strong> counts its <strong>approved P.O. amount</strong> on the approved-on date (or the date billed when there is none), or its <strong>approved quote total</strong> on the decision date.</li><li>Imported actuals count for the shop and sales person they were imported for.</li><li>Jobs in an excluded status (Cancelled and No-show by default) do not count.</li></ul><h3 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h3><ul><li><strong>My performance</strong> (Sales) or <strong>Leaderboard</strong> (Owner): <strong>Quota</strong>, <strong>Actual</strong>, <strong>%</strong>, <strong>Surplus / deficit</strong>, <strong>QTD S/D</strong>. Press <strong>Why this counts</strong> on a row to see every job or import behind the number.</li><li><strong>Performers</strong>: reps at or above the performer threshold (100% of quota by default).</li><li>Owner only: <strong>Sales mix by nature</strong>, <strong>Sales mix by insurer</strong>, <strong>Mix reconciliation</strong>, and the company total.</li></ul><h3 id="owner-quotas-and-importing-the-old-workbooks" tabindex="-1">Owner: quotas and importing the old workbooks <a class="header-anchor" href="#owner-quotas-and-importing-the-old-workbooks" aria-label="Permalink to &quot;Owner: quotas and importing the old workbooks&quot;">​</a></h3><ol><li>Edit each rep&#39;s monthly <strong>Quota</strong> and press <strong>Save quotas</strong>. Changes are kept under <strong>Quota changes</strong>.</li><li>Press <strong>Import Excel</strong> and choose a monthly Sales Monitoring workbook or a per-agent workbook (<code>.xlsx</code>).</li><li><strong>Preview</strong> the quotas and <strong>Approved LOA/P.O.</strong> actuals, and read the <strong>Warnings</strong> (bad dates, <code>#REF!</code> cells, blank amounts).</li><li><strong>Map reps</strong> to staff, or <strong>Keep as unmatched text</strong>.</li><li>Tick <strong>Include quotas</strong>, <strong>Include actuals</strong>, <strong>Skip rows already counted</strong>, then <strong>Import</strong>.</li><li>Every upload is listed in <strong>Import history</strong>. <strong>Undo</strong> removes that batch.</li></ol><h2 id="_4-4-commissions-and-incentives" tabindex="-1">4.4 Commissions and incentives <a class="header-anchor" href="#_4-4-commissions-and-incentives" aria-label="Permalink to &quot;4.4 Commissions and incentives&quot;">​</a></h2><h3 id="the-commission-rule-shop-defaults" tabindex="-1">The commission rule (shop defaults) <a class="header-anchor" href="#the-commission-rule-shop-defaults" aria-label="Permalink to &quot;The commission rule (shop defaults)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rule</th><th>Default</th></tr></thead><tbody><tr><td>Who earns</td><td>The staff member set as <strong>Referred by (staff)</strong> on the job. The <strong>Sales advisor</strong> never earns.</td></tr><tr><td>Which job</td><td>The customer&#39;s <strong>first</strong> referred job at the shop. Repeat visits do not earn again.</td></tr><tr><td>Which channels</td><td>Not Walk-in, Phone, Messenger or Website (the &quot;no-commission&quot; channels). Sales-channel inquiries earn.</td></tr><tr><td>Rate</td><td><strong>5%</strong> of the basis</td></tr><tr><td>Basis</td><td><strong>Customer cash collected</strong> (what the customer actually paid)</td></tr><tr><td>Floor</td><td>If the basis is under <strong>PHP 30,000</strong>, the fee is waived (&quot;Below the commission floor, so no sales commission on this job.&quot;)</td></tr><tr><td>Maturity</td><td><strong>30 days after release</strong>, or after the customer finished paying if that is later</td></tr></tbody></table><p>The owner can change the rate, basis (Customer paid, Approved amount, Net of cost), floor, waiting days and channels in <strong>Admin › Shop settings › Sales &amp; commission</strong>.</p><p><strong>Example:</strong> you refer a new customer; the job releases on 1 March with PHP 48,000 customer cash collected. Fee = 5% × 48,000 = <strong>PHP 2,400</strong>, due on 31 March. If the customer paid only PHP 25,000 (insurance covered the rest), the basis is under the PHP 30,000 floor and no fee is created.</p><div class="warning custom-block"><p class="custom-block-title">Referral is set by the desk</p><p>Only the owner (or admin) sets or changes <strong>Referred by (staff)</strong> on a job, with a reason. You cannot attach yourself. If you referred a customer and do not see a line, tell the owner.</p></div><h3 id="commission-statuses-sales-me-commission" tabindex="-1">Commission statuses (<code>/sales</code>, <code>/me/commission</code>) <a class="header-anchor" href="#commission-statuses-sales-me-commission" aria-label="Permalink to &quot;Commission statuses (`/sales`, `/me/commission`)&quot;">​</a></h3><p><strong>Accruing</strong> → <strong>Due</strong> → <strong>Approved</strong> → <strong>Paid</strong> (or <strong>Void</strong>).</p><ul><li><strong>Fees</strong> view: Job, Sales, Type, Referred by, Fee, Status, Due date, Payout ref. Use the date range and <strong>Download CSV</strong>.</li><li><strong>Payouts</strong> view: Date, Amount, Method, Reference, Proof, Jobs.</li></ul><p><strong>Owner:</strong> <strong>Approve</strong> or <strong>Reject</strong> due lines, then <strong>Pay due fees</strong> — choose the Sales person, method (<strong>Bank transfer</strong> or <strong>GCash</strong>) and reference, and <strong>Mark paid</strong>. A paid fee on a job that is later un-collected (refund, credit note) appears under <strong>Needs review</strong>: <strong>Void payout</strong> to return it to due, or <strong>Dismiss</strong> with a note.</p><h3 id="quarterly-unit-incentive-sales-incentives-me-incentive" tabindex="-1">Quarterly unit incentive (<code>/sales/incentives</code>, <code>/me/incentive</code>) <a class="header-anchor" href="#quarterly-unit-incentive-sales-incentives-me-incentive" aria-label="Permalink to &quot;Quarterly unit incentive (`/sales/incentives`, `/me/incentive`)&quot;">​</a></h3><p>Separate from commission. The owner sets a <strong>Unit target</strong> and <strong>Pesos per released unit</strong> for the quarter (<strong>Set a target</strong>). Your page shows your <strong>Progress</strong> and the suggested bonus. The owner then <strong>Record bonus</strong> with the amount, reason and the payroll period it is paid in. It is added to that payroll as taxable pay. Targets only track progress; nothing is paid automatically.</p><h2 id="_4-5-insurance-premium-calculator-sales-insurance" tabindex="-1">4.5 Insurance Premium Calculator (<code>/sales/insurance</code>) <a class="header-anchor" href="#_4-5-insurance-premium-calculator-sales-insurance" aria-label="Permalink to &quot;4.5 Insurance Premium Calculator (`/sales/insurance`)&quot;">​</a></h2><p>A staff-only tool to give a customer a quick motor insurance premium estimate. It is not a policy and does not bind cover.</p><ol><li>Pick the <strong>Vehicle type</strong> (value band).</li><li>Choose <strong>TPL</strong> or <strong>Comprehensive</strong>.</li><li>Tick any add-ons.</li><li>Read the <strong>Estimate</strong> (annual premium and range).</li><li>Press <strong>Save estimate</strong>, link it to a <strong>Pipeline inquiry</strong> or type the <strong>Customer name</strong> and <strong>Plate</strong>, add notes, and save.</li></ol><p><strong>Saved estimates</strong> can be printed and moved through <strong>Draft → Sent → Won / Lost</strong> (Mark sent, Mark won, Mark lost). Search by customer, plate or car.</p><p><strong>Owner only:</strong> the <strong>Rate table</strong> (TPL rate, Comprehensive rate, range spread, value bands with representative values, add-ons with amounts). Press <strong>Save</strong>.</p><div class="info custom-block"><p class="custom-block-title">📷 Screenshot placeholder</p><p><code>/screenshots/04-sales-agent-guide/02-insurance-calculator.png</code> — Insurance estimate with vehicle type, coverage and add-ons.</p></div>',43)])])}const p=t(r,[["render",a]]);export{u as __pageData,p as default};
